<?php

namespace App\Pipstream;

use Illuminate\Support\Facades\Log;
use Illuminate\Support\Facades\Redis;
use InvalidArgumentException;
use Throwable;

/**
 * Laravel's side of the PipStream event bus (Redis Streams). Envelopes are byte-compatible
 * with the engine's `pipstream.common.events.Event`:
 *   {event_id, topic, trace_id, occurred_at, producer, payload}
 *
 * Laravel may only publish the topics below; Redis ACLs enforce the same list server-side
 * (generated by the engine's permissions.py), so the web app can never write trade.intent.
 */
class Bus
{
    public const PUBLISH = ['config.changed', 'billing.changed', 'tg.login.request', 'user.command'];

    public const CONSUME = ['trade.executed', 'trade.failed', 'trade.closed', 'risk.limit_hit',
        'signal.rejected', 'tg.login.status'];

    public function redis()
    {
        return Redis::connection('streams');
    }

    public function key(string $topic): string
    {
        return config('pipstream.stream_prefix').':stream:'.$topic;
    }

    /** @return array the envelope that was published */
    public function publish(string $topic, array $payload, ?string $traceId = null): array
    {
        if (! in_array($topic, self::PUBLISH, true)) {
            throw new InvalidArgumentException("laravel may not publish {$topic}");
        }
        $event = [
            'event_id' => Ids::new('evt'),
            'topic' => $topic,
            'trace_id' => $traceId ?? Ids::new('tr'),
            'occurred_at' => now()->utc()->format('Y-m-d\TH:i:s.uP'),
            'producer' => 'laravel',
            'payload' => $payload,
        ];
        $this->redis()->client()->xAdd($this->key($topic), '*',
            ['e' => json_encode($event, JSON_UNESCAPED_SLASHES)], (int) config('pipstream.stream_maxlen'), true);

        return $event;
    }

    /**
     * Consume topics in the "laravel" consumer group until $shouldStop() returns true.
     * At-least-once: a failing handler is retried (entries reclaimed after $claimIdleMs) and
     * dead-lettered to ps:stream:dlq after $maxDeliveries, like the engine's Bus.
     *
     * @param  callable(array $event): void  $handler
     */
    public function consume(array $topics, callable $handler, string $consumer, ?callable $shouldStop = null,
        int $blockMs = 2000, int $claimIdleMs = 10000, int $maxDeliveries = 5): void
    {
        $r = $this->redis()->client();
        $group = config('pipstream.consumer_group');
        $keys = array_map(fn ($t) => $this->key($t), $topics);
        foreach ($keys as $k) {
            try {
                $r->xGroup('CREATE', $k, $group, '0', true);
            } catch (Throwable $e) {
                if (! str_contains($e->getMessage(), 'BUSYGROUP')) {
                    throw $e;
                }
            }
            $r->clearLastError();
        }
        $deliveries = config('pipstream.stream_prefix').':deliveries:laravel';
        $lastClaim = 0.0;

        $process = function (string $key, string $id, array $fields) use ($r, $group, $handler, $deliveries, $maxDeliveries) {
            $raw = $fields['e'] ?? null;
            $event = $raw ? json_decode($raw, true) : null;
            if (! is_array($event) || ! isset($event['topic'], $event['payload'])) {
                $this->deadLetter($key, $id, (string) $raw, 'decode_error');
                $r->xAck($key, $group, [$id]);

                return;
            }
            try {
                $handler($event);
            } catch (Throwable $e) {
                $n = $r->hIncrBy($deliveries, "{$key}|{$id}", 1);
                Log::error('pipstream event handler failed', ['topic' => $event['topic'], 'trace_id' => $event['trace_id'] ?? null,
                    'attempt' => $n, 'error' => $e->getMessage()]);
                if ($n >= $maxDeliveries) {
                    $this->deadLetter($key, $id, $raw, $e->getMessage());
                    $r->xAck($key, $group, [$id]);
                    $r->hDel($deliveries, "{$key}|{$id}");
                }

                return;
            }
            $r->xAck($key, $group, [$id]);
        };

        while (! ($shouldStop && $shouldStop())) {
            if (microtime(true) - $lastClaim > $claimIdleMs / 1000) {
                $lastClaim = microtime(true);
                foreach ($keys as $k) {
                    foreach ($this->autoClaim($r, $k, $group, $consumer, $claimIdleMs) as $id => $fields) {
                        if ($fields) {
                            $process($k, (string) $id, $fields);
                        }
                    }
                }
            }
            $streams = array_fill_keys($keys, '>');
            $resp = $r->xReadGroup($group, $consumer, $streams, 50, $blockMs);
            foreach (($resp ?: []) as $key => $entries) {
                foreach ($entries as $id => $fields) {
                    $process((string) $key, (string) $id, $fields);
                }
            }
        }
    }

    /** XAUTOCLAIM via the raw command so it works on phpredis 5 and 6 alike. @return array<string, array> */
    private function autoClaim($r, string $key, string $group, string $consumer, int $idleMs): array
    {
        $res = $r->rawCommand('XAUTOCLAIM', $key, $group, $consumer, (string) $idleMs, '0-0', 'COUNT', '50');
        $out = [];
        foreach (($res[1] ?? []) as $entry) {
            if (! is_array($entry) || ! is_array($entry[1] ?? null)) {
                continue;   // entry deleted from the stream meanwhile
            }
            $f = [];
            for ($i = 0; $i + 1 < count($entry[1]); $i += 2) {
                $f[$entry[1][$i]] = $entry[1][$i + 1];
            }
            $out[(string) $entry[0]] = $f;
        }

        return $out;
    }

    private function deadLetter(string $key, string $id, string $raw, string $reason): void
    {
        $this->redis()->client()->xAdd($this->key('dlq'), '*',
            ['stream' => $key, 'id' => $id, 'reason' => mb_substr($reason, 0, 500), 'e' => $raw],
            (int) config('pipstream.stream_maxlen'), true);
    }
}
